/**
 * `agent-sdk pagerduty …` — replay synthesized PagerDuty v3 webhooks into a
 * local `pagerdutyChannel()` and list the discovered PagerDuty channels.
 *
 * PagerDuty subscriptions POST to a public URL, so live deliveries need a
 * tunnel. Replay covers the local loop without one or a PagerDuty account:
 * it builds v3 bodies for an incident and signs `X-PagerDuty-Signature`
 * from `--secret` / `PAGERDUTY_WEBHOOK_SECRET` (unsigned when neither is
 * set, which `serve --dev` admits from loopback).
 */
import { randomUUID } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import { join, resolve as resolvePath } from "node:path";
import { channelForwardUrl } from "../channels/github/forward.js";
import { findPagerDutyChannelTargets, } from "../channels/pagerduty/pagerduty-channel.js";
import { PAGERDUTY_SIGNATURE_HEADER, PAGERDUTY_WEBHOOK_SECRET_ENV, signPagerDutyWebhookBody, } from "../channels/pagerduty/pagerduty-webhook.js";
import { PAGERDUTY_REPLAY_DEFAULT_INCIDENT_ID, PAGERDUTY_REPLAYABLE_EVENTS, selectPagerDutyReplayEvents, synthesizePagerDutyEvent, } from "../channels/pagerduty/replay.js";
import { resolveAgentMounts } from "./discovery.js";
import { parseHmacSecrets } from "./hmac-secret-values.js";
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
import { projectPath, resolveProjectRoot } from "./project-layout.js";
const DEFAULT_HOST = "127.0.0.1";
const DEFAULT_PORT = 3000;
const PAGERDUTY_HELP = `${CLI} pagerduty — replay PagerDuty v3 webhooks into a local agent

Usage:
  ${CLI} pagerduty replay  [incident_id] [--events a,b,c | *] [--comment "…"]
                                [--dir .] [--slug S] [--channel C]
                                [--host H] [--port N] [--url URL] [--secret S]
                                [--dry-run] [--out DIR] [--json]
  ${CLI} pagerduty events  [--dir .] [--host H] [--port N] [--json]

Commands:
  replay    Synthesize v3 webhook bodies for one incident (default
            ${PAGERDUTY_REPLAY_DEFAULT_INCIDENT_ID}) and POST them, in order, to the discovered
            pagerdutyChannel()s. --events picks them (default triggered;
            \`*\` = every declared event replay supports:
            ${PAGERDUTY_REPLAYABLE_EVENTS.join(", ")}).
            A trigger comes from PagerDuty itself; the rest come from a
            person, so they dispatch. --comment is the note body for
            annotated. Signs X-PagerDuty-Signature from --secret /
            ${PAGERDUTY_WEBHOOK_SECRET_ENV} (its first line when it lists several).
            --dry-run prints the bodies; --out writes them as fixtures.
  events    List discovered PagerDuty channels and the event types each accepts.

Prerequisites:
  - The agent already serving (\`${CLI} dev\` or \`${CLI} serve --dir . --dev\`).
`;
export async function cmdPagerDuty(subcommand, options) {
    switch (subcommand) {
        case undefined:
        case "help":
        case "--help":
        case "-h":
            process.stdout.write(PAGERDUTY_HELP);
            return subcommand === undefined ? 1 : 0;
        case "replay":
            return cmdPagerDutyReplay(options);
        case "events":
            return cmdPagerDutyEvents(options);
        default:
            process.stderr.write(`Unknown pagerduty subcommand: ${subcommand}\n`);
            process.stdout.write(PAGERDUTY_HELP);
            return 1;
    }
}
function targetUrl(target, options) {
    return channelForwardUrl({
        host: options.host ?? DEFAULT_HOST,
        port: options.port ?? DEFAULT_PORT,
        slug: target.slug,
        channelId: target.channelId,
        routePath: target.routePath,
    });
}
async function resolveTargets(options) {
    const dir = resolvePath(options.dir);
    let candidates = findPagerDutyChannelTargets(await resolveAgentMounts(dir));
    if (options.slug !== undefined) {
        candidates = candidates.filter((c) => c.slug === options.slug);
    }
    if (options.channel !== undefined) {
        candidates = candidates.filter((c) => c.channelId === options.channel);
    }
    if (options.url !== undefined) {
        if (candidates.length > 1) {
            process.stderr.write("--url targets a single channel; narrow with --slug/--channel\n");
            return undefined;
        }
        return [
            {
                slug: candidates[0]?.slug ?? "",
                channelId: candidates[0]?.channelId ?? "",
                url: options.url,
                events: candidates[0]?.events ?? [],
            },
        ];
    }
    if (candidates.length === 0) {
        const channelPath = projectPath(resolveProjectRoot(dir), "channels/pagerduty.ts");
        process.stderr.write(`no PagerDuty channel found. Author ${channelPath} with pagerdutyChannel(), or pass --url.\n`);
        return undefined;
    }
    return candidates.map((c) => ({
        slug: c.slug,
        channelId: c.channelId,
        url: targetUrl(c, options),
        events: c.events,
    }));
}
async function cmdPagerDutyReplay(options) {
    const targets = await resolveTargets(options);
    if (targets === undefined) {
        return 1;
    }
    const declared = [...new Set(targets.flatMap((target) => target.events))];
    const { events, unsupported } = selectPagerDutyReplayEvents({
        requested: parseEventList(options.events),
        declared,
    });
    if (unsupported.length > 0) {
        process.stderr.write(`[bdk] cannot synthesize (skipped): ${unsupported.join(", ")}\n`);
    }
    if (events.length === 0) {
        process.stderr.write("no synthesizable events selected\n");
        return 1;
    }
    const incidentId = options.incidentId ?? PAGERDUTY_REPLAY_DEFAULT_INCIDENT_ID;
    // A secret that lists one value per subscription signs with its first.
    const parsedSecret = parseHmacSecrets(options.secret ?? process.env[PAGERDUTY_WEBHOOK_SECRET_ENV]?.trim());
    const secret = parsedSecret.ok ? parsedSecret.secrets[0] : undefined;
    if (options.json !== true) {
        process.stderr.write(`[bdk] replaying incident ${incidentId} (${events.join(", ")}) → ${targets.length} channel${targets.length === 1 ? "" : "s"}${secret === undefined ? " unsigned" : ""}\n`);
    }
    const report = [];
    let anyRejected = false;
    for (const eventType of events) {
        const payload = synthesizePagerDutyEvent({ eventType, incidentId, note: options.comment });
        const body = JSON.stringify(payload);
        const headers = {
            "content-type": "application/json",
            "x-webhook-id": randomUUID(),
        };
        if (secret !== undefined) {
            headers[PAGERDUTY_SIGNATURE_HEADER] = signPagerDutyWebhookBody({ rawBody: body, secret });
        }
        if (options.out !== undefined) {
            const file = await writeReplayFixture(options.out, eventType, payload);
            if (options.json !== true) {
                process.stderr.write(`[bdk] wrote ${file}\n`);
            }
        }
        if (options.dryRun === true) {
            report.push({ event: eventType, payload });
            if (options.json !== true) {
                process.stdout.write(`--- ${eventType} ---\n${JSON.stringify(payload, null, 2)}\n`);
            }
            continue;
        }
        const deliveries = await deliverReplayEvent(body, headers, eventType, targets);
        if (deliveries.length === 0 || deliveries.some((d) => !d.ok)) {
            anyRejected = true;
        }
        report.push({ event: eventType, deliveries });
        if (options.json !== true) {
            const summary = deliveries
                .map((d) => `${d.label} ${d.status || "ERR"}${d.ok ? "" : " (rejected)"}`)
                .join(", ") || "(no matching channel)";
            process.stderr.write(`[bdk]   ${eventType} → ${summary}\n`);
        }
    }
    if (options.json === true) {
        process.stdout.write(`${JSON.stringify({
            incidentId,
            signed: secret !== undefined,
            dryRun: options.dryRun === true,
            events: report,
        }, null, 2)}\n`);
    }
    return anyRejected ? 1 : 0;
}
async function deliverReplayEvent(body, headers, eventType, targets) {
    const recipients = targets.filter((target) => target.events.length === 0 || target.events.includes(eventType));
    const deliveries = [];
    // In order, not in parallel: one incident's events must arrive as a sequence.
    for (const target of recipients) {
        const label = target.slug === "" ? target.channelId : `${target.slug}/${target.channelId}`;
        try {
            const response = await fetch(target.url, { method: "POST", headers, body });
            await response.text().catch(() => undefined);
            deliveries.push({ label, status: response.status, ok: response.ok });
        }
        catch (error) {
            deliveries.push({
                label,
                status: 0,
                ok: false,
                error: error instanceof Error ? error.message : String(error),
            });
        }
    }
    return deliveries;
}
async function writeReplayFixture(outDir, eventType, payload) {
    const dir = resolvePath(outDir);
    await mkdir(dir, { recursive: true });
    const file = join(dir, `pagerduty-${eventType.replace(/[^\w-]+/g, "-")}.json`);
    await writeFile(file, `${JSON.stringify(payload, null, 2)}\n`);
    return file;
}
async function cmdPagerDutyEvents(options) {
    const dir = resolvePath(options.dir);
    const rows = findPagerDutyChannelTargets(await resolveAgentMounts(dir)).map((c) => ({
        slug: c.slug,
        channelId: c.channelId,
        url: targetUrl(c, options),
        events: c.events,
    }));
    if (options.json === true) {
        process.stdout.write(`${JSON.stringify({ channels: rows }, null, 2)}\n`);
        return 0;
    }
    if (rows.length === 0) {
        process.stdout.write("no PagerDuty channels found\n");
        return 0;
    }
    for (const row of rows) {
        const label = row.slug === "" ? row.channelId : `${row.slug}/${row.channelId}`;
        process.stdout.write(`${label}\n  ${row.url}\n  ${row.events.join(", ")}\n`);
    }
    return 0;
}
function parseEventList(value) {
    if (value === undefined) {
        return undefined;
    }
    const events = value
        .split(/[\s,]+/)
        .map((event) => event.trim())
        .filter(Boolean);
    return events.length === 0 ? undefined : events;
}
